"""Table of the queue-8 final checkpoints scored against the fixed GT (evaluate_final.txt) and against GT scaled to each run's training box
convention (evaluate_final_gtscaled.txt, HM_GT_BOX_COEF; see evaluation.set_gt_box_coef). +nms, floor 0.1, top-225. Output: hm_runs/newbox/results_table_newbox_gtscaled.md"""
import json, re, os
ROOT = '/mnt/DATA/mlgidDETECT_DINO_HEATMAP/hm_runs/newbox'
RUNS = ['hm_simmim_frozen_ridge_tf32_seed1_newbox_2.00_2.00', 'hm_simmim_frozen_ridge_tf32_seed2_newbox_2.00_2.00', 'hm_simmim_frozen_ridge_tf32_seed42_newbox_2.00_2.00',
        'hm_simmim_frozen_ridge_tf32_seed42_newbox_2.50_2.50', 'hm_simmim_frozen_ridge_tf32_seed42_newbox_2.80_1.30', 'hm_simmim_frozen_ridge_tf32_seed42_newbox_3.00_3.00',
        'hm_simmim_frozen_ridge_tf32_seed42_newbox_3.50_3.50', 'hm_simmim_frozen_ridge_tf32_seed42_newbox_4.00_4.00']
RUNS += [f'hm_simmim_frozen_ridge_tf32_seed{s}_newbox_{b}_{b}_galvani' for b in ('2.5', '3.0', '3.5', '4.0') for s in (1, 2)]      # Galvani replicates (a100-galvani), files from origin/heatmap heatmap/galvani_results/
RUNS += [f'hm_simmim_frozen_ridge_tf32_seed{s}_newbox_{b}_{b}' for b in ('3.50', '4.00') for s in (1, 2)]      # queue 10 replicates (colorbox1), appear once evaluated
RUNS = [r for r in RUNS if os.path.exists(f'{ROOT}/{r}/evaluate_final_gtscaled.txt')]      # queue 9 runs appear once they are evaluated


def parse(path):
    """-> {set: (ap, recall0.3, prec0.3, ring0.3, fp0.3)} of the [hm+nms] block, plus the printed GT scale line."""
    out, ds, blk, scale = {}, None, False, None
    for ln in open(path, errors='replace'):
        m = re.match(r'\s+GT box scale \(x,y\):\s*(.*)', ln)
        if m: scale = m.group(1).strip()
        m = re.match(r'\s+\[hm\+nms\] (\S+): ap_total ([\d.]+)', ln)
        if m: ds, blk = m.group(1), True; out[ds] = [float(m.group(2))]; continue
        if re.match(r'\s+\[hm \(native\)\]', ln): blk = False
        m = re.match(r'\s+score>0\.3: recall ([\d.]+) \(seg [\d.]+, ring ([\d.]+)\) precision ([\d.]+) preds \d+ FP (\d+)', ln)
        if m and blk and ds: out[ds] += [float(m.group(1)), float(m.group(3)), float(m.group(2)), int(m.group(4))]; blk = False
    return out, scale


rows = []
for r in RUNS:
    fx, _ = parse(f'{ROOT}/{r}/evaluate_final.txt'); sc, scale = parse(f'{ROOT}/{r}/evaluate_final_gtscaled.txt')
    bc = json.load(open(f'{ROOT}/{r}/args.json'))['box_coef']; seed = json.load(open(f'{ROOT}/{r}/args.json'))['seed']
    rows.append((r, seed, bc, scale, fx, sc))
rows.sort(key=lambda x: (x[2] != '2,2', float(x[2].split(',')[0]), x[2], x[1], x[0].endswith('_galvani')))     # galvani 2.5,2.5 / 3.0,3.0 (identical coef strings to colorbox)
f = lambda v: f'{v:.4f}'
L = ['# Queue-8/9 final checkpoints: fixed GT vs GT scaled to the run\'s training box convention', '',
     'Generated by `heatmap/summarize_gtscaled.py` (no hand-edited numbers) from `evaluate_final.txt` (fixed GT, +-1 sigma) and `evaluate_final_gtscaled.txt` (GT scaled about its centre by (w_coef/2, a_coef/2), ring boxes in x only; neighbour-distance buckets on the unscaled GT; code: origin/heatmap d9b2d82, `evaluation.set_gt_box_coef`). Protocol: +nms, score floor 0.1, top-225, QMatcher min_iou 0.1; recall / precision / ring recall / FP at score > 0.3; same files `newbox_visfix`. Inference only (no retraining).', '',
     'Runs with the suffix `_galvani` are seed-1/seed-2 replicates trained and scored on the Galvani cluster (same H1 recipe, `HM_GT_BOX_COEF=auto`; copied verbatim from `origin/heatmap:heatmap/galvani_results/`); all other runs were trained on colorbox1.', '',
     '**Note on the first six runs:** `HM_GT_BOX_COEF=auto` fails in `evaluate.py` with `KeyError: \'box_coef\'` (`a[\'box_coef\']`: the `hm_args` dict stored in these checkpoints has no `box_coef`; the failed outputs are kept as `evaluate_final_gtscaled_auto_FAILED_KeyError_box_coef.txt`). The first six runs (queue 8) therefore used the documented explicit form `HM_GT_BOX_COEF=<a_coef,w_coef>` (value from each run\'s `args.json`), which sets the same scale; for those the "GT box scale (x,y)" line was written by the run wrapper. Later runs (queue 9) use HM_GT_BOX_COEF=auto with the args.json fallback of origin/heatmap 91946fc.', '',
     '| Run | Seed | box_coef | GT box scale (x,y) | AP org fixed | AP org scaled | AP 41 fixed | AP 41 scaled | Recall org fixed / scaled | Prec org fixed / scaled | Ring org fixed / scaled | FP org fixed / scaled | Recall 41 fixed / scaled | Prec 41 fixed / scaled | Ring 41 fixed / scaled | FP 41 fixed / scaled |',
     '|:--|--:|:--|:--|--:|--:|--:|--:|:--|:--|:--|:--|:--|:--|:--|:--|']
for r, seed, bc, scale, fx, sc in rows:
    def pair(ds, i, fmt=lambda v: f'{v:.3f}'): return f'{fmt(fx[ds][i])} / {fmt(sc[ds][i])}'
    L.append(f'| {r} | {seed} | {bc} | {scale} | {f(fx["organic"][0])} | {f(sc["organic"][0])} | {f(fx["41"][0])} | {f(sc["41"][0])} | '
             + ' | '.join(pair(ds, i, (lambda v: str(v)) if i == 4 else (lambda v: f'{v:.3f}')) for ds in ('organic', '41') for i in (1, 2, 3, 4)) + ' |')
ref = [x for x in rows if x[0].endswith('seed42_newbox_2.00_2.00')][0]
L += ['', '**Differences to the 2,2 seed-42 run, same GT treatment** (AP org / AP 41, scaled column; fixed column in brackets):', '']
for r, seed, bc, scale, fx, sc in rows:
    if r == ref[0]: continue
    L.append(f'- {r} (seed {seed}, {bc}): scaled {sc["organic"][0]-ref[5]["organic"][0]:+.4f} / {sc["41"][0]-ref[5]["41"][0]:+.4f} (fixed {fx["organic"][0]-ref[4]["organic"][0]:+.4f} / {fx["41"][0]-ref[4]["41"][0]:+.4f})')
two = [x for x in rows if x[2] == '2,2']
for ds, nm in (('organic', 'organic'), ('41', '41')):
    v = [x[5][ds][0] for x in two]; m = sum(v) / len(v); sd = (sum((a - m) ** 2 for a in v) / (len(v) - 1)) ** .5
    L.append(f'- 2,2 seeds (1, 2, 42), AP {nm}: mean {m:.4f} +- {sd:.4f} SD (scale (1.0, 1.0): identical to the fixed GT)')
L += ['', '**Seed groups per box_coef** (mean +- SD, n>=2; AP org / AP 41; scaled GT). Where Galvani replicates exist the core group is Galvani seeds 1, 2 + colorbox seed 42; colorbox seed-1/2 runs (queue 10) are separate rows and added in the "all runs" line:', '']
def sel_group(g, tag):
    def ms(ds):
        v = [x[5][ds][0] for x in g]; m = sum(v) / len(v); return f'{m:.4f} +- {(sum((a - m) ** 2 for a in v) / (len(v) - 1)) ** .5:.4f}'
    return f'- {tag}, n={len(g)} ({", ".join(("galvani " if x[0].endswith("_galvani") else "colorbox ") + "seed " + str(x[1]) for x in g)}): {ms("organic")} / {ms("41")}'
for bc in sorted({x[2] for x in rows}, key=lambda b: float(b.split(',')[0])):
    g = [x for x in rows if x[2] == bc]
    core = [x for x in g if x[0].endswith('_galvani') or x[1] == 42] if any(x[0].endswith('_galvani') for x in g) else g
    if len(core) >= 2: L.append(sel_group(core, bc))
    if len(core) != len(g): L.append(sel_group(g, bc + ' all runs'))
open(f'{ROOT}/results_table_newbox_gtscaled.md', 'w').write('\n'.join(L) + '\n')
print('\n'.join(L))
